#!/usr/bin/env bash
printf "%s\n" "$(tput bold)$(date) ${BASH_SOURCE[0]}$(tput sgr0)"

# Generated by Gemini on Sun Nov 15 16:29:00 MST 2026
# Context: dantopa@isomer:~/repos-isomer/github/jop/c++/pagmo
# invocation: ./probe-cxx-pagmo-env.sh 2>&1 | tee probe-cxx-pagmo-env.log

(
set -euo pipefail

START_TIME=$(date +%s)
STEP_COUNT=0
SUBSTEP_COUNT=0

new_step() {
    STEP_COUNT=$((STEP_COUNT + 1))
    SUBSTEP_COUNT=0
    printf "\n================================================================================\n"
    printf "[STEP %02d] %s\n" "${STEP_COUNT}" "$1"
    printf "================================================================================\n"
}

sub_step() {
    SUBSTEP_COUNT=$((SUBSTEP_COUNT + 1))
    printf "\n--- [STEP %02d.%02d] %s ---\n" "${STEP_COUNT}" "${SUBSTEP_COUNT}" "$1"
}

display_total_elapsed_time() {
    local end_time
    end_time=$(date +%s)
    local elapsed=$((end_time - START_TIME))
    printf "\n================================================================================\n"
    printf "TOTAL ELAPSED TIME: %02dm %02ds\n" $((elapsed / 60)) $((elapsed % 60))
    printf "================================================================================\n"
}

trap display_total_elapsed_time EXIT

# ------------------------------------------------------------------------------
new_step "Host & Operating System Identification"
# ------------------------------------------------------------------------------
sub_step "System Kernel, Architecture & OS Release"
printf "Host:         %s\n" "$(hostname)"
printf "User:         %s\n" "$(whoami)"
printf "Kernel:       %s\n" "$(uname -srm)"
if [[ -r /etc/os-release ]]; then
    # shellcheck disable=SC1091
    source /etc/os-release
    printf "OS Release:   %s\n" "${PRETTY_NAME:-Unknown}"
fi
printf "CPU Threads:  %s\n" "$(nproc 2>/dev/null || echo 'unknown')"

# ------------------------------------------------------------------------------
new_step "Spack Environment & Activation Status"
# ------------------------------------------------------------------------------
sub_step "Active Spack Shell Integration & Environment"
printf "SPACK_ROOT:   %s\n" "${SPACK_ROOT:-<unset>}"
printf "SPACK_ENV:    %s\n" "${SPACK_ENV:-<unset>}"

SPACK_CMD=""
if command -v spack >/dev/null 2>&1; then
    SPACK_CMD="$(command -v spack)"
    printf "spack on PATH: YES (%s)\n" "${SPACK_CMD}"
else
    printf "spack on PATH: NO\n"
    for candidate in \
        "${HOME}/spacktivity/genesis/bin/spack" \
        "${HOME}/spack/bin/spack" \
        "/opt/spack/bin/spack"; do
        if [[ -x "${candidate}" ]]; then
            SPACK_CMD="${candidate}"
            printf "spack found on disk: %s (not sourced in current shell)\n" "${SPACK_CMD}"
            break
        fi
    done
fi

sub_step "Spack Installed Packages Check (pagmo2, boost, eigen, tbb, mpi)"
if [[ -n "${SPACK_CMD}" ]]; then
    "${SPACK_CMD}" find --format "{name}@{version}%{compiler} /{hash:7} -> {prefix}" \
        pagmo2 boost eigen intel-tbb tbb openmpi mpich 2>/dev/null || true
        printf "No matching Spack packages found in default scope.\n"
else
    printf "Skipping Spack query: no spack executable found.\n"
fi

# ------------------------------------------------------------------------------
new_step "C++ Compilers, Build Tools & MPI Probe"
# ------------------------------------------------------------------------------
sub_step "C/C++ Compilers & CMake/Make"
for tool in g++ gcc clang++ clang cmake make pkg-config; do
    if command -v "${tool}" >/dev/null 2>&1; then
        ver="$("${tool}" --version 2>/dev/null | head -n 1)"
        printf "%-14s FOUND -> %s (%s)\n" "${tool}:" "$(command -v "${tool}")" "${ver}"
    else
        printf "%-14s MISSING\n" "${tool}:"
    fi
done

sub_step "MPI Wrappers & Runtime"
for mpi_tool in mpicxx mpic++ mpicc mpiexec mpirun; do
    if command -v "${mpi_tool}" >/dev/null 2>&1; then
        ver="$("${mpi_tool}" --version 2>/dev/null | head -n 1)"
        printf "%-14s FOUND -> %s (%s)\n" "${mpi_tool}:" "$(command -v "${mpi_tool}")" "${ver}"
    else
        printf "%-14s MISSING\n" "${mpi_tool}:"
    fi
done

# ------------------------------------------------------------------------------
new_step "System & Environment Search Paths (CPATH / LIBRARY_PATH / System Dirs)"
# ------------------------------------------------------------------------------
sub_step "Compiler Environment Variables"
printf "CPATH:            %s\n" "${CPATH:-<unset>}"
printf "CPLUS_INCLUDE_PATH: %s\n" "${CPLUS_INCLUDE_PATH:-<unset>}"
printf "LIBRARY_PATH:     %s\n" "${LIBRARY_PATH:-<unset>}"
printf "LD_LIBRARY_PATH:  %s\n" "${LD_LIBRARY_PATH:-<unset>}"
printf "CMAKE_PREFIX_PATH:%s\n" "${CMAKE_PREFIX_PATH:-<unset>}"

sub_step "System Ubuntu Package & Header Check (/usr/include & dpkg)"
if [[ -f /usr/include/pagmo/algorithm.hpp ]]; then
    printf "System pagmo header: FOUND (/usr/include/pagmo/algorithm.hpp)\n"
else
    printf "System pagmo header: NOT FOUND in /usr/include/pagmo/\n"
fi

if command -v dpkg-query >/dev/null 2>&1; then
    dpkg-query -W -f='${Package} ${Version} (${Status})\n' \
        'libpagmo*' 'libboost-dev' 'libeigen3-dev' 'libtbb-dev' 'libopenmpi-dev' 2>/dev/null || true
fi

# ------------------------------------------------------------------------------
new_step "Live C++ Compilation & Link Smoke Test for pagmo2"
# ------------------------------------------------------------------------------
sub_step "Testing Direct g++ Compile (Without Spack Flags)"
TMP_DIR="$(mktemp -d)"
cat << 'CPP_EOF' > "${TMP_DIR}/smoke.cpp"
#include <iostream>
#include <pagmo/config.hpp>
#include <pagmo/problem.hpp>
#include <pagmo/problems/rosenbrock.hpp>

int main() {
    pagmo::problem p{pagmo::rosenbrock{2}};
    std::cout << "pagmo " << PAGMO_VERSION_MAJOR << "."
              << PAGMO_VERSION_MINOR << "." << PAGMO_VERSION_PATCH
              << " linked OK (dim=" << p.get_nx() << ")\n";
    return 0;
}
CPP_EOF

if g++ -std=c++17 "${TMP_DIR}/smoke.cpp" -lpagmo -ltbb -lpthread -o "${TMP_DIR}/smoke_direct" 2>"${TMP_DIR}/direct.err"; then
    printf "Direct g++ compile: SUCCESS -> %s\n" "$("${TMP_DIR}/smoke_direct")"
else
    printf "Direct g++ compile: FAILED (compiler cannot see pagmo2 by default)\n"
    sed 's/^/  | /' "${TMP_DIR}/direct.err"
fi

sub_step "Testing g++ Compile Using Spack Location Flags"
if [[ -n "${SPACK_CMD}" ]] && PAGMO_PREFIX="$("${SPACK_CMD}" location -i pagmo2 2>/dev/null)"; then
    BOOST_PREFIX="$("${SPACK_CMD}" location -i boost 2>/dev/null || true)"
    EIGEN_PREFIX="$("${SPACK_CMD}" location -i eigen 2>/dev/null || true)"
    TBB_PREFIX="$("${SPACK_CMD}" location -i intel-tbb 2>/dev/null || "${SPACK_CMD}" location -i tbb 2>/dev/null || true)"

    INC_FLAGS=(-I"${PAGMO_PREFIX}/include")
    [[ -n "${BOOST_PREFIX}" ]] && INC_FLAGS+=(-I"${BOOST_PREFIX}/include")
    [[ -n "${EIGEN_PREFIX}" ]] && INC_FLAGS+=(-I"${EIGEN_PREFIX}/include/eigen3")
    [[ -n "${TBB_PREFIX}" ]]   && INC_FLAGS+=(-I"${TBB_PREFIX}/include")

    LIB_FLAGS=(-L"${PAGMO_PREFIX}/lib" -L"${PAGMO_PREFIX}/lib64" -Wl,-rpath,"${PAGMO_PREFIX}/lib" -Wl,-rpath,"${PAGMO_PREFIX}/lib64")
    if [[ -n "${BOOST_PREFIX}" ]]; then
        LIB_FLAGS+=(-L"${BOOST_PREFIX}/lib" -Wl,-rpath,"${BOOST_PREFIX}/lib")
    fi
    if [[ -n "${TBB_PREFIX}" ]]; then
        LIB_FLAGS+=(-L"${TBB_PREFIX}/lib" -L"${TBB_PREFIX}/lib64" -Wl,-rpath,"${TBB_PREFIX}/lib" -Wl,-rpath,"${TBB_PREFIX}/lib64")
    fi

    if g++ -std=c++17 "${INC_FLAGS[@]}" "${TMP_DIR}/smoke.cpp" "${LIB_FLAGS[@]}" -lpagmo -ltbb -lpthread -o "${TMP_DIR}/smoke_spack" 2>"${TMP_DIR}/spack.err"; then
        printf "Spack-guided g++ compile: SUCCESS -> %s\n" "$("${TMP_DIR}/smoke_spack")"
    else
        printf "Spack-guided g++ compile: FAILED\n"
        sed 's/^/  | /' "${TMP_DIR}/spack.err"
    fi
else
    printf "Skipping Spack-guided compile: pagmo2 prefix not found via Spack.\n"
fi

rm -rf "${TMP_DIR}"
)
